import argparse
import re
import sys
from collections import Counter


def parse_args():
    parser = argparse.ArgumentParser(
        description="Print the top N most frequent words in a text file."
    )
    parser.add_argument("filename", help="Path to the text file")
    parser.add_argument("n", type=int, help="Number of top words to display")
    return parser.parse_args()


def read_words(filename):
    try:
        with open(filename, "r", encoding="utf-8") as file_handle:
            raw_text = file_handle.read()
    except FileNotFoundError:
        print(f"Error: file not found: {filename}", file=sys.stderr)
        sys.exit(1)
    except OSError as os_error:
        print(f"Error reading file: {os_error}", file=sys.stderr)
        sys.exit(1)

    raw_words = re.findall(r"[a-zA-Z]+", raw_text)
    normalized_words = [word.lower() for word in raw_words]
    return normalized_words


def get_top_words(word_list, top_n):
    word_counts = Counter(word_list)
    return word_counts.most_common(top_n)


def print_word_counts(top_word_list):
    for word, count in top_word_list:
        print(f"{word}: {count}")


def main():
    args = parse_args()

    if args.n <= 0:
        print("Error: N must be a positive integer.", file=sys.stderr)
        sys.exit(1)

    word_list = read_words(args.filename)

    if not word_list:
        print("No words found in the file.", file=sys.stderr)
        sys.exit(1)

    top_word_list = get_top_words(word_list, args.n)
    print_word_counts(top_word_list)


if __name__ == "__main__":
    main()

