from contextlib import asynccontextmanager
from typing import Any

from fastapi import Depends, FastAPI, HTTPException, Request
from pydantic import BaseModel


@asynccontextmanager
async def lifespan(app: FastAPI):
    app.state.store = {}
    yield
    app.state.store.clear()


app = FastAPI(lifespan=lifespan)


class PutBody(BaseModel):
    value: Any


def get_store(request: Request) -> dict:
    return request.app.state.store


@app.get("/items")
def list_items(store: dict = Depends(get_store)) -> dict:
    return store


@app.get("/items/{key}")
def get_item(key: str, store: dict = Depends(get_store)) -> Any:
    if key not in store:
        raise HTTPException(status_code=404, detail=f"Key '{key}' not found")
    return store[key]


@app.put("/items/{key}", status_code=200)
def put_item(key: str, body: PutBody, store: dict = Depends(get_store)) -> dict:
    store[key] = body.value
    return {"key": key, "value": body.value}


@app.delete("/items/{key}", status_code=200)
def delete_item(key: str, store: dict = Depends(get_store)) -> dict:
    if key not in store:
        raise HTTPException(status_code=404, detail=f"Key '{key}' not found")
    del store[key]
    return {"deleted": key}

