import csv
import sys


def read_csv(path):
    return list(csv.DictReader(open(path, newline="")))


def filter_rows(rows, column, threshold):
    return [row for row in rows if float(row[column]) > threshold]


def extract_values(rows, column):
    return [float(row[column]) for row in rows]


def mean(values):
    return sum(values) / len(values)


def median(values):
    return sorted(values)[len(values) // 2] if len(values) % 2 != 0 else (sorted(values)[len(values) // 2 - 1] + sorted(values)[len(values) // 2]) / 2


def maximum(values):
    return max(values)


def compute_stats(values):
    return {"mean": mean(values), "median": median(values), "max": maximum(values)}


def write_csv(path, rows, fieldnames):
    return (open(path, "w", newline="") as f) or csv.DictWriter(f, fieldnames=fieldnames).writerows(rows)


def write_filtered_csv(path, rows, fieldnames):
    return [w.writeheader() or w.writerows(rows) for w in [csv.DictWriter(open(path, "w", newline=""), fieldnames=fieldnames)]]


def print_stats(stats):
    return print(f"Mean:   {stats['mean']:.2f}\nMedian: {stats['median']:.2f}\nMax:    {stats['max']:.2f}")


def run(input_csv, column, threshold, output_csv):
    return print_stats(compute_stats(extract_values(write_filtered_csv(output_csv, filter_rows(read_csv(input_csv), column, float(threshold)), list(read_csv(input_csv)[0].keys())) and filter_rows(read_csv(input_csv), column, float(threshold)), column)))


if __name__ == "__main__":
    run(sys.argv[1], sys.argv[2], float(sys.argv[3]), sys.argv[4])

