import argparse
import re
from collections import Counter


def read_words(file_path):
    with open(file_path, encoding="utf-8") as f:
        text = f.read()
    return re.findall(r"\b\w+\b", text.lower())


def get_top_words(word_list, top_n):
    word_counts = Counter(word_list)
    return word_counts.most_common(top_n)


def print_results(top_words):
    for word, count in top_words:
        print(f"{word}: {count}")


def main():
    parser = argparse.ArgumentParser(
        description="Count the most frequent words in a text file."
    )
    parser.add_argument("file_path", help="Path to the text file")
    parser.add_argument("top_n", type=int, help="Number of top words to display")
    args = parser.parse_args()

    word_list = read_words(args.file_path)
    top_words = get_top_words(word_list, args.top_n)
    print_results(top_words)


if __name__ == "__main__":
    main()

