import csv
import statistics
import sys


def load_and_filter(input_path: str, column: str, threshold: float) -> list[dict]:
    with open(input_path, newline="") as f:
        reader = csv.DictReader(f)
        if reader.fieldnames is None or column not in reader.fieldnames:
            raise ValueError(f"Column '{column}' not found in CSV headers.")
        return [row for row in reader if float(row[column]) > threshold]


def compute_stats(rows: list[dict], column: str) -> dict:
    values = [float(row[column]) for row in rows]
    if not values:
        raise ValueError("No rows remain after filtering; cannot compute statistics.")
    return {
        "mean": statistics.mean(values),
        "median": statistics.median(values),
        "max": max(values),
    }


def write_csv(output_path: str, rows: list[dict]) -> None:
    if not rows:
        return
    with open(output_path, "w", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=rows[0].keys())
        writer.writeheader()
        writer.writerows(rows)


def main(argv: list[str]) -> int:
    if len(argv) != 5:
        print(
            f"Usage: {argv[0]} <input.csv> <column_name> <threshold> <output.csv>",
            file=sys.stderr,
        )
        return 1

    _, input_path, column, threshold_str, output_path = argv

    try:
        threshold = float(threshold_str)
    except ValueError:
        print(f"Error: threshold must be a number, got '{threshold_str}'.", file=sys.stderr)
        return 1

    try:
        filtered = load_and_filter(input_path, column, threshold)
    except FileNotFoundError:
        print(f"Error: input file '{input_path}' not found.", file=sys.stderr)
        return 1
    except ValueError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return 1

    print(f"Rows after filtering: {len(filtered)}")

    try:
        stats = compute_stats(filtered, column)
    except ValueError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return 1

    print(f"Mean:   {stats['mean']:.4f}")
    print(f"Median: {stats['median']:.4f}")
    print(f"Max:    {stats['max']:.4f}")

    write_csv(output_path, filtered)
    print(f"Filtered data written to '{output_path}'.")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

