    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        if reader.fieldnames is None:
            return [], []
        headers = list(reader.fieldnames)
        rows = list(reader)
    return headers, rows


def filter_rows(rows: list[dict[str, str]], column: str, threshold: float) -> list[dict[str, str]]:
    result = []
    for row in rows:
        if column not in row:
            sys.exit(f"Error: column '{column}' not found in row.")
        try:
            value = float(row[column])
        except ValueError:
            sys.exit(f"Error: non-numeric value '{row[column]}' in column '{column}'.")
        if value > threshold:
            result.append(row)
    return result


def compute_statistics(rows: list[dict[str, str]], column: str) -> dict[str, float]:
    if not rows:
        return {"mean": float("nan"), "median": float("nan"), "max": float("nan")}
