import csv
import statistics
import sys


def load_and_filter(input_path: str, column: str, threshold: float) -> tuple[list[dict], list[float]]:
    """Read CSV, return filtered rows and the numeric values for the target column."""
    try:
        with open(input_path, newline="", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            if reader.fieldnames is None or column not in reader.fieldnames:
                # Read one row to trigger fieldnames population, then check
                rows = list(reader)
                if column not in (reader.fieldnames or []):
                    available = ", ".join(reader.fieldnames or [])
                    raise ValueError(
                        f"Column '{column}' not found. Available columns: {available}"
                    )
            else:
                rows = list(reader)
    except FileNotFoundError:
        raise FileNotFoundError(f"Input file not found: '{input_path}'")

    if not rows:
        raise ValueError(f"Input file '{input_path}' is empty or has no data rows.")

    filtered_rows: list[dict] = []
