import argparse
import re
from collections import Counter


def count_words(text):
    words = re.findall(r"[a-zA-Z']+", text.lower())
    return Counter(words)


def main():
    parser = argparse.ArgumentParser(
        description="Print the N most frequent words in a text file."
    )
    parser.add_argument("filename", help="Path to the text file")
    parser.add_argument("N", type=int, help="Number of top words to display")
    args = parser.parse_args()

    with open(args.filename, "r", encoding="utf-8") as f:
        text = f.read()

    counts = count_words(text)
    for word, freq in counts.most_common(args.N):
        print(f"{word} {freq}")


if __name__ == "__main__":
    main()

