import argparse
import string
from collections import Counter


def parse_args():
    parser = argparse.ArgumentParser(
        description="Print the N most frequent words in a text file."
    )
    parser.add_argument("filename", help="Path to the text file")
    parser.add_argument("n", type=int, help="Number of top words to display")
    return parser.parse_args()


def tokenize(text):
    translator = str.maketrans("", "", string.punctuation)
    return [word.lower().translate(translator) for word in text.split() if word.translate(translator)]


def read_words(filename):
    with open(filename, "r", encoding="utf-8") as f:
        return tokenize(f.read())


def top_n_words(words, n):
    return Counter(words).most_common(n)


def main():
    args = parse_args()

    if args.n <= 0:
        print("Error: N must be a positive integer.")
        raise SystemExit(1)

    try:
        words = read_words(args.filename)
    except FileNotFoundError:
        print(f"Error: File '{args.filename}' not found.")
        raise SystemExit(1)

    for word, count in top_n_words(words, args.n):
        print(f"{word}: {count}")


if __name__ == "__main__":
    main()

