"""CLI utility: print the N most frequent words in a text file."""

import argparse
import re
from collections import Counter


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Print the N most frequent words in a text file."
    )
    parser.add_argument("filename", help="Path to the text file to analyse")
    parser.add_argument("n", type=int, help="Number of top words to display")
    return parser.parse_args()


def count_words(text: str) -> Counter:
    words = re.findall(r"[a-zA-Z']+", text.lower())
    return Counter(words)


def format_results(counter: Counter, n: int) -> str:
    lines = [f"{word}\t{count}" for word, count in counter.most_common(n)]
    return "\n".join(lines)


def main() -> None:
    args = parse_args()
    with open(args.filename, encoding="utf-8") as fh:
        text = fh.read()
    counter = count_words(text)
    print(format_results(counter, args.n))


if __name__ == "__main__":
    main()

