import csv
import sys


def read_csv(path): return list(csv.DictReader(open(path, newline="")))

def filter_rows(rows, column, threshold): return [r for r in rows if float(r[column]) > threshold]

def calc_mean(rows, column): return sum(float(r[column]) for r in rows) / len(rows)

def calc_median(rows, column): return (lambda s: (s[len(s) // 2] if len(s) % 2 else (s[len(s) // 2 - 1] + s[len(s) // 2]) / 2))(sorted(float(r[column]) for r in rows))

def calc_max(rows, column): return max(float(r[column]) for r in rows)

def write_csv(rows, path): return (lambda w: [w.writeheader(), w.writerows(rows)])(csv.DictWriter(open(path, "w", newline=""), fieldnames=rows[0].keys()))

def print_stats(mean, median, maximum): return print(f"mean={mean:.2f}, median={median:.2f}, max={maximum:.2f}")


def main():
    input_file, column, threshold, output_file = sys.argv[1], sys.argv[2], float(sys.argv[3]), sys.argv[4]
    rows = read_csv(input_file)
    filtered = filter_rows(rows, column, threshold)
    mean = calc_mean(filtered, column)
    median = calc_median(filtered, column)
    maximum = calc_max(filtered, column)
    print_stats(mean, median, maximum)
    write_csv(filtered, output_file)


if __name__ == "__main__":
