import csv
import statistics
import sys
from typing import NamedTuple


class FilterResult(NamedTuple):
    rows: list[dict[str, str]]
    mean: float
    median: float
    maximum: float


def read_csv(path: str) -> list[dict[str, str]]:
    with open(path, newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def filter_rows(rows: list[dict[str, str]], column: str, threshold: float) -> list[dict[str, str]]:
    return [row for row in rows if float(row[column]) > threshold]


def compute_stats(rows: list[dict[str, str]], column: str) -> tuple[float, float, float]:
    values = [float(row[column]) for row in rows]
    if not values:
        raise ValueError(f"No rows remain after filtering — cannot compute statistics.")
    return (
        statistics.mean(values),
        statistics.median(values),
        max(values),
    )


def write_csv(path: str, rows: list[dict[str, str]], fieldnames: list[str]) -> None:
    with open(path, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(rows)


def run(input_path: str, output_path: str, column: str, threshold: float) -> FilterResult:
    all_rows = read_csv(input_path)
    if not all_rows:
        raise ValueError("Input CSV is empty.")
    if column not in all_rows[0]:
        raise KeyError(f"Column '{column}' not found. Available: {list(all_rows[0].keys())}")

    filtered = filter_rows(all_rows, column, threshold)
    mean, median, maximum = compute_stats(filtered, column)
    write_csv(output_path, filtered, fieldnames=list(all_rows[0].keys()))
    return FilterResult(rows=filtered, mean=mean, median=median, maximum=maximum)


if __name__ == "__main__":
    if len(sys.argv) != 5:
        print("Usage: filter_csv.py <input.csv> <output.csv> <column> <threshold>")
        sys.exit(1)

    _, input_csv, output_csv, col_name, threshold_str = sys.argv
    result = run(input_csv, output_csv, col_name, float(threshold_str))

    print(f"Rows kept   : {len(result.rows)}")
    print(f"Mean        : {result.mean:.4f}")
    print(f"Median      : {result.median:.4f}")
    print(f"Maximum     : {result.maximum:.4f}")
    print(f"Output written to: {output_csv}")

