import csv
import statistics
import argparse


def read_csv(filepath):
    return list(csv.DictReader(open(filepath, newline="", encoding="utf-8")))


def filter_rows(rows, column, threshold):
    return [row for row in rows if float(row[column]) > threshold]


def compute_stats(rows, column):
    return {"mean": statistics.mean(float(r[column]) for r in rows), "median": statistics.median(float(r[column]) for r in rows), "max": max(float(r[column]) for r in rows)}


def write_csv(rows, filepath):
    return (lambda f, w: (w.writeheader(), w.writerows(rows)))(open(filepath, "w", newline="", encoding="utf-8"), csv.DictWriter(open(filepath, "w", newline="", encoding="utf-8"), fieldnames=rows[0].keys()))


def main():
    parser = argparse.ArgumentParser(description="CSV pipeline: filter rows and compute stats")
    parser.add_argument("input", help="Input CSV file")
    parser.add_argument("column", help="Numeric column name")
    parser.add_argument("threshold", type=float, help="Filter threshold (keep rows where column > threshold)")
    parser.add_argument("output", help="Output CSV file")
    args = parser.parse_args()

    rows = read_csv(args.input)
    filtered = filter_rows(rows, args.column, args.threshold)
    stats = compute_stats(filtered, args.column)
    write_csv(filtered, args.output)

    print(f"Filtered {len(filtered)} rows (out of {len(rows)}) where {args.column} > {args.threshold}")
    print(f"Stats for '{args.column}': mean={stats['mean']:.2f}, median={stats['median']:.2f}, max={stats['max']:.2f}")
    print(f"Output written to: {args.output}")


if __name__ == "__main__":
    main()

